package com.spinfit.bike.ui;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.Bundle;import android.widget.*;
public final class GuideActivity extends Activity{
 @Override protected void onCreate(Bundle b){super.onCreate(b);LinearLayout r=Ui.root(this);r.addView(Ui.topBar(this,"4 周入门路线",this::finish));r.addView(Ui.eyebrow(this,"BUILD A HABIT"));r.addView(Ui.title(this,"循序渐进，骑得长久。"));r.addView(Ui.sub(this,"以下是基于通用运动原则编排的示例路线，不是机构官方课程。每周隔日安排 3 次，疲劳时重复上一周或休息。"));
  String[][] weeks={{"01","建立习惯","周二  轻松入门 20 分钟\n周四  轻松入门 20 分钟\n周六  舒缓恢复 20 分钟","beginner"},{"02","延长一点","周二  基础有氧 30 分钟\n周四  轻松入门 20 分钟\n周六  基础有氧 30 分钟","endurance"},{"03","稳定积累","周二  基础有氧 30 分钟\n周四  基础有氧 30 分钟\n周六  基础有氧 30 分钟","endurance"},{"04","从容进步","周二  基础有氧 30 分钟\n周四  舒缓恢复 20 分钟\n周六  有氧耐力 45 分钟","zone2"}};
  for(String[] w:weeks){Ui.gap(this,r,18);LinearLayout c=Ui.card(this);c.addView(Ui.eyebrow(this,"WEEK "+w[0]));Ui.gap(this,c,10);c.addView(Ui.tv(this,w[1],21,Ui.TEXT,true));Ui.gap(this,c,12);TextView schedule=Ui.tv(this,w[2],14,Ui.DIM,false);schedule.setLineSpacing(Ui.dp(this,8),1);c.addView(schedule);Ui.gap(this,c,16);Button go=Ui.button(this,"查看本周主要课程  →",Ui.CARD2,Ui.TEXT);go.setOnClickListener(v->ProgramDetailActivity.open(this,w[3]));c.addView(go);r.addView(c);}
  r.addView(Ui.section(this,"记住这三件事",null,null));r.addView(Ui.tv(this,"01  每次先热身，再进入主训练\n\n结构化课程安排至少 5 分钟热身与放松。\n\n02  用呼吸判断强度\n\n中等强度通常还能说话，但难以唱歌。踏频和功率是参考，先保证动作舒适。\n\n03  先增加时长，再考虑强度\n\n入门路线用于渐进建立习惯，并不等于已达到每周运动总量建议。可搭配步行等活动，并安排力量训练。胸痛、头晕或异常气短时停止运动。",14,Ui.DIM,false));
  r.addView(Ui.section(this,"资料来源",null,null));source(r,"CDC · 成人每周活动建议","成人每周至少 150 分钟中等强度，另有 2 天力量训练。","https://www.cdc.gov/physical-activity-basics/guidelines/adults.html");source(r,"CDC · 对话测试与体感强度","中等强度可以说话但难以唱歌，强度应结合个人体能。","https://www.cdc.gov/physical-activity-basics/measuring/index.html");source(r,"AHA · 热身与放松","热身 5–10 分钟，结束后逐步降低运动强度。","https://www.heart.org/en/healthy-living/exercise-and-physical-activity/fitness-basics/warm-up-cool-down");Ui.screen(this,r,null);
 }
 private void source(LinearLayout r,String title,String text,String url){LinearLayout c=Ui.card(this);c.addView(Ui.tv(this,title+"  ↗",14,Ui.TEXT,true));Ui.gap(this,c,8);c.addView(Ui.sub(this,text));c.setOnClickListener(v->{try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}catch(Exception e){Ui.dialog(this,"资料链接",url);}});Ui.touch(c,Ui.CARD,22);Ui.add(this,r,c,12);}
}
